import functools
import time


def retry(times, exceptions=(Exception,), delay=0.0, backoff=2.0, sleep=time.sleep):
    """Retry the wrapped callable on matching exceptions.

    The callable is tried at most `times` times. Between failed attempts it
    waits `delay * backoff ** (attempt - 1)` seconds via `sleep`. The final
    exception is re-raised unchanged. `wrapper.last_attempts` records how many
    calls the most recent invocation made.
    """
    if times < 1:
        raise ValueError(f"times must be >= 1, got {times}")
    if delay < 0:
        raise ValueError(f"delay must be >= 0, got {delay}")
    if backoff < 1:
        raise ValueError(f"backoff must be >= 1, got {backoff}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wrapper.last_attempts = 0
            while True:
                wrapper.last_attempts += 1
                attempt = wrapper.last_attempts
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt >= times:
                        raise
                    if delay:
                        sleep(delay * backoff ** (attempt - 1))

        wrapper.last_attempts = 0
        return wrapper

    return decorator

